<style>
:root{color-scheme:light;--pi-ink:#171b19;--pi-muted:#646b65;--pi-edge:#e8e8e8;--pi-bg:#f7f7f8;--pi-nav:#fff;--pi-accent:#994b00;--pi-orange:#f9941d;--pi-orange-soft:#fff1e0}
*{box-sizing:border-box}body{margin:0;background:var(--pi-bg);color:var(--pi-ink);font:14px/1.6 Arial,Helvetica,sans-serif}
.pi-layout{display:grid;grid-template-columns:245px minmax(0,1fr);min-height:100vh}.pi-sidebar{background:var(--pi-nav);color:var(--pi-ink);padding:30px 22px;border-right:1px solid var(--pi-edge);display:flex;flex-direction:column;gap:18px}
.pi-brand{display:grid;gap:10px;max-width:190px}.pi-brand img{display:block;max-width:100%;width:180px;height:auto;object-fit:contain}.pi-brand small{display:block;color:#767676;font-size:11px;letter-spacing:.04em;font-weight:500;padding-left:1px}
.pi-nav-title{margin:14px 12px 0;color:#7a7a7a;font-size:10px;line-height:1.4;font-weight:700;letter-spacing:.14em;text-transform:uppercase}
.pi-sidebar nav{margin-top:18px}.pi-sidebar ul{list-style:none;padding:0;display:grid;gap:6px}.pi-sidebar li>span{display:block;padding:12px 14px;border-radius:8px;color:#565b57;font-size:12px}.pi-sidebar .pi-current{background:var(--pi-orange-soft);color:#8b4400;font-weight:700;border-left:3px solid var(--pi-orange);padding-left:11px}
.pi-sidebar-note{font-size:11px;color:#6c716c;border-top:1px solid var(--pi-edge);padding-top:18px;margin-top:auto}
.pi-main{max-width:1550px;width:100%;padding:32px clamp(16px,4vw,48px);margin:0 auto;min-width:0}.pi-header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:24px;background:#fff;border:1px solid var(--pi-edge);border-radius:10px;padding:20px 24px}
h1{font-size:clamp(26px,3vw,36px);letter-spacing:-.035em;margin:4px 0}h2{font-size:18px;margin:0 0 14px}p{margin:8px 0}.pi-eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.1em;font-weight:800;color:var(--pi-accent)}.pi-muted{color:var(--pi-muted);font-size:13px}
.pi-content{display:grid;gap:20px;margin-top:24px}.pi-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.pi-grid-two{grid-template-columns:repeat(2,minmax(0,1fr))}
.pi-panel{min-width:0;border:1px solid var(--pi-edge);background:#fff;border-radius:10px;padding:22px;box-shadow:0 7px 24px #171b1906;overflow-wrap:anywhere}.pi-service h2{margin-top:18px}
.pi-badge{display:inline-block;border:1px solid currentColor;border-radius:99px;padding:4px 10px;font-size:12px;font-weight:700;overflow-wrap:anywhere}.pi-tone-neutral{background:#f2f2f2;color:#565b57}.pi-tone-info{background:#fff1e0;color:#854100}.pi-tone-success{background:#edf8f0;color:#256239}.pi-tone-warning{background:#fff7e6;color:#78520c}.pi-tone-error{background:#fff0f0;color:#972b2b}
.pi-message{padding:16px 20px;border:1px solid currentColor;border-radius:12px;overflow-wrap:anywhere}.pi-message p{font-size:13px;margin-bottom:0}.pi-metric-label{color:var(--pi-muted);font-size:14px;font-weight:500}.pi-number{font-size:32px;font-weight:800;letter-spacing:-.04em}
.pi-table-wrap{overflow-x:auto;border-radius:8px}.pi-table-hint{margin:0 0 8px}.pi-table-wrap table{min-width:36rem}table{border-collapse:collapse;width:100%;text-align:left}caption{text-align:left;font-weight:700;padding:12px 8px}th,td{padding:14px 8px;border-bottom:1px solid var(--pi-edge);overflow-wrap:anywhere}th{font-size:12px;color:var(--pi-muted)}td{font-size:14px}
.pi-list{padding-left:22px}.pi-list li{padding:8px 0;border-bottom:1px solid var(--pi-edge)}.pi-empty{padding:24px 12px;text-align:center;color:var(--pi-muted)}.pi-loading{display:flex;align-items:center;gap:12px;padding:16px}.pi-skeleton{display:inline-block;width:40px;height:18px;border-radius:6px;background:#e8e8e8}
.pi-skip{position:absolute;top:8px;left:8px;transform:translateY(-180%);background:#fff;color:#854100;padding:10px;z-index:10}.pi-skip:focus{transform:none}a:focus-visible,[tabindex]:focus-visible{outline:3px solid #9b4d00;outline-offset:4px}footer{text-align:center;color:var(--pi-muted);font-size:12px;margin-top:28px}
@media(max-width:1050px){.pi-layout{grid-template-columns:1fr;align-content:start}.pi-sidebar{padding:18px 22px;border-right:0;border-bottom:1px solid var(--pi-edge);gap:8px}.pi-sidebar nav{margin-top:18px}.pi-sidebar ul{grid-template-columns:repeat(3,minmax(0,1fr))}.pi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.pi-header{display:block;padding:18px}.pi-brand img{width:150px}.pi-header>.pi-badge{margin-top:12px}.pi-sidebar ul{grid-template-columns:1fr}.pi-grid{grid-template-columns:1fr}.pi-panel{padding:18px}.pi-main{padding-top:22px}}
.pi-stage-title{margin-top:16px}.pi-journey-progress{width:100%;height:12px;accent-color:var(--pi-orange)}
.pi-journey{padding-left:24px;margin-bottom:0}.pi-journey li{padding:18px 0 18px 12px;border-bottom:1px solid var(--pi-edge)}.pi-journey li:last-child{border:0}.pi-journey h3{font-size:16px;margin:10px 0 4px}.pi-journey p{color:var(--pi-muted)}
.pi-record{margin:16px 0}.pi-record>div{display:grid;grid-template-columns:minmax(0,150px) minmax(0,1fr);gap:12px;padding:10px 0;border-bottom:1px solid var(--pi-edge)}.pi-record dt{font-size:13px;color:var(--pi-muted)}.pi-record dd{margin:0;min-width:0}
.pi-request-list{list-style:none;margin:0;padding:0;display:grid;gap:20px}.pi-request-list>li{min-width:0}
.pi-update-history{margin-top:20px;border-top:1px solid var(--pi-edge);padding-top:16px}.pi-update-history h4{font-size:15px;margin:0 0 8px}.pi-updates{padding-left:24px}.pi-updates li{padding:10px 0 10px 8px}
@media(max-width:1050px){.pi-record>div{grid-template-columns:minmax(0,1fr);gap:4px}}
@media(max-width:640px){.pi-sidebar{padding:15px 16px;gap:8px}.pi-nav-title{margin:8px 0 0}.pi-sidebar nav{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:thin;margin:5px 0 0;padding:2px 0 10px}.pi-sidebar ul{display:grid;grid-auto-flow:column;grid-template-columns:none;grid-auto-columns:max-content;gap:6px;width:max-content}.pi-sidebar li>span{white-space:nowrap;padding:10px 12px}.pi-sidebar .pi-current{padding-left:9px}.pi-sidebar-note{margin:0;padding-top:10px;font-size:10px}}

</style>
